parameters.jsCode:
// Referencia explícita a los dos agentes (este nodo va después del Verificador).
const a = $('Agente').first().json.output ?? {};
const audit = (a && typeof a === 'object') ? a : { respuesta: String(a ?? '') };
let verif = null;
try { verif = $('Agente Verificador').first().json.output ?? null; } catch (e) { verif = null; }
return [{ json: { output: audit.respuesta ?? '', auditoria: audit, verificacion: verif } }];

parameters.inputSchema:
{
  "type": "object",
  "required": [
    "respuesta",
    "etapa",
    "productos_ofrecidos"
  ],
  "properties": {
    "respuesta": {
      "type": "string",
      "description": "el texto tal cual le llega al cliente por WhatsApp; lo único que él ve"
    },
    "etapa": {
      "type": "string",
      "enum": [
        "saludo",
        "recomendacion",
        "falta_info",
        "seguimiento",
        "otro"
      ],
      "description": "la etapa del flujo en la que actuaste"
    },
    "productos_ofrecidos": {
      "type": "array",
      "description": "un item por producto que le mostraste al cliente; vacío si no recomendaste ninguno",
      "items": {
        "type": "object",
        "required": [
          "nombre_catalogo",
          "atributos"
        ],
        "properties": {
          "nombre_catalogo": {
            "type": "string",
            "description": "el nombre EXACTO como vino de buscar_catalogo, sin reformular"
          },
          "nombre_mostrado": {
            "type": "string",
            "description": "cómo lo nombraste en tu respuesta al cliente (puede diferir del de catálogo)"
          },
          "atributos": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "atributos concretos que le afirmaste a ESTE producto (medida, faz, material, color, acabado). Cada uno tiene que salir de la MISMA fila de la búsqueda"
          },
          "cantidad": {
            "type": [
              "number",
              "null"
            ],
            "description": "cantidad que el cliente pidió para este producto, si la mencionó; sino null"
          }
        }
      }
    },
    "motivo": {
      "type": "string",
      "description": "en una línea, por qué elegiste esos productos / esa respuesta"
    },
    "afirmaciones": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "otras afirmaciones concretas sobre el negocio o el producto, corroborables contra el catálogo; sin saludos ni relleno"
    }
  }
}

